      'fr':{ex:{main:'2 premières formes de Baduanjin',sub:'10 min chaque matin\nMouvements : Soutenir le Ciel + Élévation Rate-Estomac'},diet:{main:'Thé Astragale-Dattes',sub:'Astragale 15g + 5 dattes rouges\nInfuser le matin, siroter toute la journée'},life:{main:'Dormir avant 23h',sub:'Horaire fixe meilleur pour le Qi\nSieste de 15 min aide'}},
      'de':{ex:{main:'Erste 2 Baduanjin-Formen',sub:'10 Min. jeden Morgen\nBewegungen: Himmel stützen + Milz-Magen-Hebung'},diet:{main:'Astragalus-Dattel-Tee',sub:'Astragalus 15g + 5 rote Datteln\nMorgens aufbrühen, den ganzen Tag nippen'},life:{main:'Vor 23 Uhr schlafen',sub:'Fester Zeitplan am besten für Qi\n15-Min.-Mittagsschlaf hilft'}},
