      'es':[{phase:'Días 1–30',title:'Calmar la Mente, Nutrir el Yin',icon:'🌙',items:['Dormir antes de las 11pm, sin excepciones','Agua de goji-ofiópogon como té diario','Seis Sonidos Curativos "Sss", 5 min/día']},{phase:'Días 31–60',title:'Nutrir el Yin, Limpiar el Calor',icon:'💧',items:['Tai Chi introductorio, 3×/semana','Sopa de lirio y hongo blanco, 2×/semana','Reducir el consumo de alimentos picantes']},{phase:'Días 61–90',title:'Consolidar los Fluidos Yin',icon:'✨',items:['Agregar natación una vez por semana','Mantener el ritmo de sueño; evaluar calidad del sueño','Repetir evaluación, notar mejora en el calor en palmas/plantas']}],
