      'pt':[{phase:'Dias 1–30',title:'Acalmar a Mente, Nutrir o Yin',icon:'🌙',items:['Dormir antes das 23h, sem exceções','Água de goji-ofiópogon como chá diário','Seis Sons Curativos "Sss", 5 min/dia']},{phase:'Dias 31–60',title:'Nutrir o Yin, Limpar o Calor',icon:'💧',items:['Tai Chi introdutório, 3×/semana','Sopa de lírio e cogumelo branco, 2×/semana','Reduzir o consumo de alimentos picantes']},{phase:'Dias 61–90',title:'Consolidar os Fluidos Yin',icon:'✨',items:['Adicionar natação uma vez por semana','Manter o ritmo de sono; avaliar qualidade do sono','Refazer avaliação, observar melhora no calor nas palmas/plantas']}],
      'ar':[{phase:'الأيام 1-30',title:'تهدئة العقل وتغذية اليين',icon:'🌙',items:['النوم قبل الساعة 11 مساءً بلا استثناء','ماء الغوجي والأوفيوبوغون كشاي يومي','أصوات الشفاء الستة "السين" 5 دقائق/يوم']},{phase:'الأيام 31-60',title:'تغذية اليين وتصفية الحرارة',icon:'💧',items:['تايتشي مبتدئ 3 مرات/أسبوع','حساء الزنبق وفطر أبيض مرتين/أسبوع','تقليل استهلاك الأطعمة الحارة']},{phase:'الأيام 61-90',title:'توطيد سوائل اليين',icon:'✨',items:['إضافة السباحة مرة في الأسبوع','الحفاظ على إيقاع النوم وتقييم جودته','إعادة التقييم وملاحظة تحسن حرارة الراحتين والأخمصين']}],
