      'en':[{phase:'Days 1–30',title:'Kickstart Metabolism',icon:'🚶',items:['Walk 20 min after each meal','Barley-adzuki porridge for breakfast, 3×/week','Reduce refined carb intake by 50%']},{phase:'Days 31–60',title:'Intensify Exercise',icon:'🏊',items:['Upgrade aerobics: brisk walk 45 min, 5×/week','Tangerine peel-poria tea daily','Add full Baduanjin set to morning routine']},{phase:'Days 61–90',title:'Consolidate Habits',icon:'💪',items:['Add swimming (best exercise for removing dampness)','Dietary habits established — maintain them','Retake assessment; note weight and mental clarity']}],
      'ja':[{phase:'1〜30日目',title:'代謝を起動する',icon:'🚶',items:['食後ごとに20分歩く','はと麦・小豆粥を朝食に週3回','精製炭水化物の摂取を50%減らす']},{phase:'31〜60日目',title:'運動を強化する',icon:'🏊',items:['有酸素運動を強化：速歩45分、週5回','陳皮・茯苓茶を毎日飲む','八段錦の全セットを朝の運動に加える']},{phase:'61〜90日目',title:'習慣を定着させる',icon:'💪',items:['水泳を追加（最高の祛湿運動）','食習慣が確立したので維持する','体質テストを再受験し体重と頭のすっきり感を確認']}],
      'ko':[{phase:'1~30일',title:'대사 시동 걸기',icon:'🚶',items:['매 식사 후 20분 걷기','보리 팥죽 아침식사 주 3회','정제 탄수화물 섭취 50% 줄이기']},{phase:'31~60일',title:'운동 강화하기',icon:'🏊',items:['유산소 운동 업그레이드: 빠른 걷기 45분, 주 5회','진피 복령차 매일 음용','팔단금 전체 세트를 아침 운동에 추가']},{phase:'61~90일',title:'습관 정착시키기',icon:'💪',items:['수영 추가(최고의 거습 운동)','식습관이 형성되었으므로 계속 유지','체질 검사 재실시하여 체중과 두뇌 명료도 확인']}],
