      'de':[{phase:'Tage 1–30',title:'Stoffwechsel ankurbeln',icon:'🚶',items:['20 Min. nach jeder Mahlzeit gehen','Gerste-Adzuki-Brei zum Frühstück, 3×/Woche','Raffinierte Kohlenhydrate um 50% reduzieren']},{phase:'Tage 31–60',title:'Bewegung intensivieren',icon:'🏊',items:['Aerobik steigern: zügiges Gehen 45 Min., 5×/Woche','Mandarinenschalten-Poria-Tee täglich','Vollständige Baduanjin-Reihe zur Morgenroutine hinzufügen']},{phase:'Tage 61–90',title:'Gewohnheiten festigen',icon:'💪',items:['Schwimmen hinzufügen (beste Übung gegen Feuchtigkeit)','Ernährungsgewohnheiten etabliert — beibehalten','Bewertung wiederholen; Gewicht und geistige Klarheit notieren']}],
      'pt':[{phase:'Dias 1–30',title:'Iniciar o Metabolismo',icon:'🚶',items:['Caminhar 20 min após cada refeição','Papa de cevada e feijão adzuki no café da manhã, 3×/semana','Reduzir a ingestão de carboidratos refinados em 50%']},{phase:'Dias 31–60',title:'Intensificar o Exercício',icon:'🏊',items:['Melhorar o aeróbico: caminhada rápida 45 min, 5×/semana','Chá de casca de tangerina e poria diariamente','Adicionar a série completa de Baduanjin à rotina matinal']},{phase:'Dias 61–90',title:'Consolidar Hábitos',icon:'💪',items:['Adicionar natação (melhor exercício para remover umidade)','Hábitos alimentares estabelecidos — mantê-los','Refazer avaliação; observar peso e clareza mental']}],
      'ar':[{phase:'الأيام 1-30',title:'إطلاق الأيض',icon:'🚶',items:['المشي 20 دقيقة بعد كل وجبة','عصيدة الشعير والفول الأزوكي للإفطار 3 مرات/أسبوع','تقليل الكربوهيدرات المكررة بنسبة 50%']},{phase:'الأيام 31-60',title:'تكثيف الرياضة',icon:'🏊',items:['تطوير الأيروبيك: مشي سريع 45 دقيقة 5 مرات/أسبوع','شاي قشر اليوسفي والبوريا يومياً','إضافة مجموعة با دوان جين الكاملة للروتين الصباحي']},{phase:'الأيام 61-90',title:'توطيد العادات',icon:'💪',items:['إضافة السباحة (أفضل رياضة لإزالة الرطوبة)','العادات الغذائية راسخة — استمر بها','إعادة التقييم؛ لاحظ الوزن ووضوح الذهن']}],
