      'de':{ex:{main:'45-Min.-Ausdauersport',sub:'Zügiges Gehen/Schwimmen/Radfahren\n5×/Woche — Kontinuität ist der Schlüssel'},diet:{main:'Gerste-Adzuki-Brei',sub:'Beste Frühstückswahl, 3×/Woche\nStärkt Milz, entfernt Feuchtigkeit'},life:{main:'30 Min. nach dem Essen gehen',sub:'Hilft der Verdauung; nicht nach dem Essen hinlegen\nJede Stunde aufstehen'}},
