      'ar':{ex:{main:'تمرين هوائي 45 دقيقة',sub:'مشي سريع/سباحة/ركوب دراجة\n5 مرات/أسبوع — المداومة هي المفتاح'},diet:{main:'عصيدة الشعير والأزوكي',sub:'أفضل اختيار للإفطار، 3 مرات/أسبوع\nيقوي الطحال ويزيل الرطوبة'},life:{main:'المشي 30 دقيقة بعد الوجبات',sub:'يساعد الهضم؛ لا تستلق بعد الأكل\nاستيقظ كل ساعة'}},
