      'es':{ex:{main:'Natación, 3×/semana',sub:'Mejor ejercicio para el calor-humedad\nParar cuando se sude ligeramente'},diet:{main:'Sopa de Mungo y Cebada',sub:'3×/semana, limpia el calor y las toxinas\nDejar el alcohol y los picantes es clave'},life:{main:'Dormir antes de las 11pm',sub:'Las noches tarde empeoran directamente el calor-humedad\nMantener movimientos intestinales regulares'}},
      'fr':{ex:{main:'Natation, 3×/semaine',sub:'Meilleur exercice pour la chaleur-humidité\nS\'arrêter quand on transpire légèrement'},diet:{main:'Soupe Mungo-Orge',sub:'3×/semaine, clarifie la chaleur et les toxines\nArrêter l\'alcool et les épices est la clé'},life:{main:'Dormir avant 23h',sub:'Les nuits tardives aggravent directement la chaleur-humidité\nMaintenir des mouvements intestinaux réguliers'}},
      'de':{ex:{main:'Schwimmen, 3×/Woche',sub:'Beste Übung gegen feuchte Hitze\nAufhören wenn leicht geschwitzt'},diet:{main:'Mungo-Gerste-Suppe',sub:'3×/Woche, klärt Hitze und Toxine\nAlkohol und scharfe Speisen meiden ist der Schlüssel'},life:{main:'Vor 23 Uhr schlafen',sub:'Späte Nächte verschlimmern direkt die feuchte Hitze\nRegelmäßigen Stuhlgang beibehalten'}},
      'pt':{ex:{main:'Natação, 3×/semana',sub:'Melhor exercício para calor-umidade\nParar quando sudar levemente'},diet:{main:'Sopa de Mungo e Cevada',sub:'3×/semana, limpa calor e toxinas\nParar o álcool e alimentos picantes é a chave'},life:{main:'Dormir antes das 23h',sub:'Noites tardias pioram diretamente o calor-umidade\nManter movimentos intestinais regulares'}},
