      'fr':{ex:{main:'Jeu de l\'Oiseau des Cinq Animaux',sub:'10 min de mouvements d\'ailes quotidiens\nAméliore le flux Qi-sang dans tout le corps'},diet:{main:'Thé Aubépine-Écorce de Mandarine',sub:'Une tasse après chaque repas\nActive le sang, dissout la stase'},life:{main:'Bouger chaque heure',sub:'Configurer des rappels téléphoniques\nRester assis trop longtemps est la cause principale'}},
      'de':{ex:{main:'Fünf-Tier-Vogelspiel',sub:'10 Min. Flügelbewegungen täglich\nVerbessert den Qi-Blut-Fluss im ganzen Körper'},diet:{main:'Weißdorn-Mandarinenschalen-Tee',sub:'Eine Tasse nach jeder Mahlzeit\nAktiviert Blut, löst Stase'},life:{main:'Jede Stunde bewegen',sub:'Telefonische Erinnerungen setzen\nLanges Sitzen ist die Hauptursache'}},
