      'en':{ex:{main:'Abdominal Deep Breathing',sub:'10 min morning and evening\n4-7-8 breathing activates vagal nerve'},diet:{main:'Rose-Jasmine Tea',sub:'Sip as daily tea\nSoothes Liver, relieves stagnation'},life:{main:'Outdoor Walk + Social',sub:'30 min outdoors daily\n1 quality social interaction/week'}},
