      'ko':{ex:{main:'복식 심호흡',sub:'아침저녁 각 10분\n4-7-8 호흡법으로 미주신경 활성화'},diet:{main:'장미 재스민 차',sub:'매일 차로 마시기\n간을 소통하고 울결 해소'},life:{main:'야외 산책+사교',sub:'매일 30분 야외\n주 1회 질 높은 사교 활동'}},
      'es':{ex:{main:'Respiración Abdominal Profunda',sub:'10 min mañana y noche\nLa respiración 4-7-8 activa el nervio vago'},diet:{main:'Té de Rosa y Jazmín',sub:'Tomar como té diario\nCalma el Hígado, alivia la estagnación'},life:{main:'Caminata al Aire Libre + Social',sub:'30 min al aire libre diariamente\n1 interacción social de calidad/semana'}},
      'fr':{ex:{main:'Respiration Abdominale Profonde',sub:'10 min matin et soir\nLa respiration 4-7-8 active le nerf vague'},diet:{main:'Thé Rose-Jasmin',sub:'À prendre comme thé quotidien\nApaise le Foie, soulage la stagnation'},life:{main:'Marche en Plein Air + Social',sub:'30 min en plein air quotidiennement\n1 interaction sociale de qualité/semaine'}},
      'de':{ex:{main:'Tiefe Bauchatmung',sub:'10 Min. morgens und abends\n4-7-8-Atmung aktiviert den Vagusnerv'},diet:{main:'Rosen-Jasmin-Tee',sub:'Als täglichen Tee trinken\nBeruhigt die Leber, löst Stagnation'},life:{main:'Spaziergang im Freien + Soziales',sub:'30 Min. täglich im Freien\n1 soziale Interaktion von Qualität/Woche'}},
      'pt':{ex:{main:'Respiração Abdominal Profunda',sub:'10 min manhã e noite\nA respiração 4-7-8 ativa o nervo vago'},diet:{main:'Chá de Rosa e Jasmim',sub:'Tomar como chá diário\nAcalma o Fígado, alivia a estagnação'},life:{main:'Caminhada ao Ar Livre + Social',sub:'30 min ao ar livre diariamente\n1 interação social de qualidade/semana'}},
      'ar':{ex:{main:'التنفس البطني العميق',sub:'10 دقائق صباحًا ومساءً\nتنفس 4-7-8 ينشط العصب المبهم'},diet:{main:'شاي الورد والياسمين',sub:'اشربه كشاي يومي\nيهدئ الكبد ويزيل الركود'},life:{main:'مشي في الهواء الطلق + التواصل الاجتماعي',sub:'30 دقيقة في الهواء الطلق يوميًا\nتفاعل اجتماعي عالي الجودة مرة/أسبوع'}},
